public static class TokenCache
{
    public static async Task<string?> GetAuthPayloadAsync(
        IDatabase redis,
        string sessionId,
        CancellationToken cancellationToken)
    {
        var value = await redis.StringGetAsync(sessionId)
            .ConfigureAwait(false);
        cancellationToken.ThrowIfCancellationRequested();
        return value.IsNullOrEmpty ? null : value.ToString();
    }
}

// WinForms button click handler on UI thread:
private void LoadData_Click(object sender, EventArgs e)
{
    // DEADLOCK: UI thread blocked in Result,
    // continuation needs UI thread to finish
    var data = LoadDataAsync().Result;
    label.Text = data;
}

private async Task<string> LoadDataAsync()
{
