    // continuation tries to post back to UI thread
    return response;
}

public async Task ProcessRequestAsync(HttpContext context)
{
    var userId = context.User.FindFirst("sub")?.Value; // capture first

    var data = await FetchDataAsync(userId!)
        .ConfigureAwait(false);

    // context may not be valid on this thread — use captured userId
    await SaveAsync(userId!, data);
}
